mapper.select:
select p.rank_id,p.rank_name,p.user_id,0 as vote_count,0 as love_count ,p.publish_time,r.rs_id,r.ranking,r.rank_update_time,r.song_id,s.song_name,si.singer_name from (select pe.rank_id,pe.rank_name,pe.publish_time,pe.user_id from personal_rank as pe where pe.category_id=#{category}
AND (pe.rank_name like concat('%',#{keyword},'%') or exists(select 1 from rank_song as rs join song as s on s.song_id=rs.song_id join singer as si on si.singer_id=s.singer_id where rs.rank_id=pe.rank_id and(si.singer_name like concat('%',#{keyword},'%') or s.song_name like concat('%',#{keyword},'%'))))
order by pe.publish_time asc limit #{pageSize} offset #{offset}) as p left join rank_song as r on p.rank_id=r.rank_id left join song as s on r.song_id = s.song_id left join singer as si on s.singer_id = si.singer_id order by r.rank_update_time asc,r.ranking desc

select p.rank_id,p.rank_name,p.user_id,0 as vote_count,0 as love_count ,p.publish_time,r.rs_id,r.ranking,r.rank_update_time,r.song_id,s.song_name,si.singer_name from (select pe.rank_id,pe.rank_name,pe.publish_time,pe.user_id from personal_rank as pe where pe.user_id=#{userId}
AND (pe.rank_name like concat('%',#{keyword},'%') or exists(select 1 from rank_song as rs join song as s on s.song_id=rs.song_id join singer as si on si.singer_id=s.singer_id where rs.rank_id=pe.rank_id and(si.singer_name like concat('%',#{keyword},'%') or s.song_name like concat('%',#{keyword},'%'))))
order by pe.publish_time asc limit 20 offset 0) as p left join rank_song as r on p.rank_id=r.rank_id left join song as s on r.song_id = s.song_id left join singer as si on s.singer_id = si.singer_id order by r.rank_update_time asc,r.ranking desc
